// The served-order composition (recommendation-sorting 3.1, design D6/D7):
// the api composes one recs EntityState per browsable entity from BATCHED
// store reads — one tag-weights read, one progress read, one watched-ledger
// read, plus the listing's own rows — feeds internal/recs, and serves
// score-desc with the alphabetical floor. Scoring is read-time and never
// persisted; the score reaches the wire solely as the additive rec_score
// field. The item listing runs D7's score-then-window: the FULL filtered set
// is read, scored, and ordered in the handler, and offset/limit apply
// afterwards — page 2 can never outrank page 1. The api keeps its own genres
// projection (INV2 bars internal/enrich here); the resolver mirrors the
// enrich walk's rule, not its code.

package api

import (
	"context"
	"database/sql"
	"errors"
	"net/http"
	"sort"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/naming"
	"github.com/mellifera/mellifera/internal/recs"
	"github.com/mellifera/mellifera/internal/store"
)

const (
	// newEpisodeWindow is D3's NEW_WINDOW: an unwatched episode bubbles its
	// started series only when discovered (item created_at) within it — flat
	// inside, none outside.
	newEpisodeWindow = 30 * 24 * time.Hour

	// photoModuleID is the photo-scanner module's registry id (the "image"
	// seed row, internal/module/registry.go): the ONE comparison behind the
	// photo carve-out — a photo library never serves a computed order and no
	// surface's score carries a context bonus for its items. The library row
	// rides the namer the scored surfaces already read — no new store read.
	photoModuleID = "image"

	// itemsPage is the paging-loop page behind the full-set item read (D7):
	// QueryItems has no unwindowed sentinel (limit <= 0 returns nil), so the
	// handler walks its id-ordered pages. The RAM is one library's filtered
	// rows — the posture browse-scale's RAM model supersedes later.
	itemsPage = 500

	// progressScanBound prices the batched progress read: the table holds
	// ONE row per item table-wide (the PutProgress upsert contract), so a
	// generous bound reads every row of the deployment in one call.
	progressScanBound = 100_000
)

// recsFacts is the batched-read scoring context one listing composes (D6):
// the learned tag affinity, the positive-progress set, and the completed
// set off the watched ledger. Three reads per REQUEST, never per row — the
// anti-N+1 posture the composition is built on.
type recsFacts struct {
	weights  recs.Weights
	progress map[string]struct{}
	watched  map[string]struct{}
	// rows is the full positive-progress set the progress map was built
	// from — the continue surface's scored rows (D7's score-then-window
	// input there). The collection listings never read it; listProgress
	// serves from it so its page cut lands AFTER the score order.
	rows []store.PlaybackProgress
}

// hasProgress reports the item's positive-progress fact (ListProgress
// serves only position_seconds > 0 rows, joined to non-deleted items —
// the store's own resume-point floor). Alone it is NOT the InProgress
// tier: completed reports whether the watch finished.
func (f recsFacts) hasProgress(itemID string) bool {
	_, has := f.progress[itemID]
	return has
}

// completed reports the item's watched-ledger fact: a watched_items row
// exists — the watch reached its completion threshold. A completed item
// keeps its positive progress row (the detector writes the ledger row
// beside it, never deleting the position), so the resume bonus needs the
// NOT-completed leg: inProgress = hasProgress && !completed.
func (f recsFacts) completed(itemID string) bool {
	_, has := f.watched[itemID]
	return has
}

// recsFactsFor batches the two scoring reads. The stored tag_weights weight
// IS the recs interest (the apply pass raises it by 1 from base per
// completion element, and recs.Score adds the base 1 itself), so the values
// pass straight into recs.Weights; keys re-fold on read through
// recs.NormalizeTag — the one tag normalization (D1) guards the read side
// the way it guards the write. Both ledger reads are the CALLING VIEWER's
// (6.2) — the tag weights stay the global learning input (5.2's invariant),
// the ledger facts scope per viewer.
func (a *app) recsFactsFor(ctx context.Context, v access.Viewer) (recsFacts, error) {
	tags, weights, err := a.deps.Store.ListTagWeights(ctx)
	if err != nil {
		return recsFacts{}, err
	}
	w := make(recs.Weights, len(tags))
	for i, tag := range tags {
		w[recs.NormalizeTag(tag)] = float64(weights[i])
	}
	rows, err := a.deps.Store.ListProgress(ctx, progressScanBound, v)
	if err != nil {
		return recsFacts{}, err
	}
	progress := make(map[string]struct{}, len(rows))
	for _, p := range rows {
		progress[p.ItemID] = struct{}{}
	}
	doneIDs, err := a.deps.Store.ListWatched(ctx, v)
	if err != nil {
		return recsFacts{}, err
	}
	watched := watchedSet(doneIDs)
	return recsFacts{weights: w, progress: progress, watched: watched, rows: rows}, nil
}

// watchedSet folds the ledger's item ids into the membership set the watched
// stamps read (watched-states D1) — the same fold recsFactsFor runs inside
// its composition. The sort=path opt-out reuses it over its own single
// ListWatched read: the stamp there needs the ledger alone, no score facts.
func watchedSet(ids []string) map[string]struct{} {
	watched := make(map[string]struct{}, len(ids))
	for _, id := range ids {
		watched[id] = struct{}{}
	}
	return watched
}

// withdrawWatched drops the ledgered rows from a progress listing's input set
// (watched-states D2): the rail's purpose is resume points, and a completed
// watch has none — its position is spent. includeWatched (the
// ?include=watched opt-in) restores them; both branches run it so the opt-out
// cannot resurrect withdrawn rows anywhere. The returned rows are exactly the
// ones that serve — the caller stamps the ledgered ones watched.
func withdrawWatched(rows []store.PlaybackProgress, watched map[string]struct{}, includeWatched bool) []store.PlaybackProgress {
	if includeWatched {
		return rows
	}
	kept := make([]store.PlaybackProgress, 0, len(rows))
	for _, row := range rows {
		if _, done := watched[row.ItemID]; !done {
			kept = append(kept, row)
		}
	}
	return kept
}

// parseSort reads a scored listing's sort opt-out (D7): absent/empty is the
// scored default; optOut restores today's store order ("path" on the
// collection listings, "recent" on the continue surface). Any other value is
// a bad request — a silently ignored sort value would serve an order the
// client cannot reason about (the progress rail's stricter-parse precedent).
func parseSort(r *http.Request, optOut string) (opted bool, bad string) {
	switch r.URL.Query().Get("sort") {
	case "":
	case optOut:
		opted = true
	default:
		bad = `sort must be "` + optOut + `" (the only opt-out; omit it for the scored default)`
	}
	return opted, bad
}

// parseInclude reads the progress listing's include grammar (watched-states
// D2): absent/empty serves the withdrawal default (ledgered rows dropped);
// "watched" restores them. Any other value is a bad request — the same
// strict-parse posture as parseSort: a silently ignored value would serve a
// row set the client cannot reason about.
func parseInclude(r *http.Request) (watched bool, bad string) {
	switch r.URL.Query().Get("include") {
	case "":
	case "watched":
		watched = true
	default:
		bad = `include must be "watched" (the only include; omit it for the withdrawal default)`
	}
	return watched, bad
}

// statusDeleted is the tombstone serve law's one api-side hard-coding of a
// lifecycle literal (tombstone-lifecycle 3.2, the LibrarySummary precedent —
// libraries.go): the canonical status set lives in internal/enrich, which the
// api MAY NOT import (INV2), but the serve contract is defined over LIVE
// items, so the default listing drops deleted rows. An explicit ?status=
// keeps exact-match semantics — ?status=deleted stays the operator's audit
// window.
const statusDeleted = "deleted"

// allFilteredItems reads the FULL filtered item set (D7's score-then-window
// input): a paging loop over QueryItems' id-ordered pages — the store has no
// unwindowed read (limit <= 0 returns nil, items.go). The filters are exactly
// listItems'; the RAM is one library's filtered rows.
//
// Tombstone serve law (tombstone-lifecycle 3.2): an EMPTY status maps here —
// once, at this shared seam — to the active-rows read: the walk drops deleted
// rows before appending, so EVERY caller (listItems' scored branch, its
// sort=path opt-out, libraryEpisodes' episode facts) inherits the default
// exclusion with no per-caller filtering — a vanished episode feeds no fact
// and stamps no Watched off its dead ledger row. Offsets page over the
// store's unfiltered batches, so the drop never perturbs pagination. An
// explicit status passes through exact-match untouched.
func (a *app) allFilteredItems(ctx context.Context, v access.Viewer, libraryID int64, status, pathPrefix string, topLevel bool) ([]store.Item, error) {
	var out []store.Item
	for offset := 0; ; offset += itemsPage {
		page, err := a.deps.Store.QueryItems(ctx, libraryID, status, pathPrefix, topLevel, itemsPage, offset, v)
		if err != nil {
			return nil, err
		}
		if status == "" {
			for i := range page {
				if page[i].Status != statusDeleted {
					out = append(out, page[i])
				}
			}
		} else {
			out = append(out, page...)
		}
		if len(page) < itemsPage {
			return out, nil
		}
	}
}

// scoreItems derives one recommendation score per item row, aligned with
// items (D2/D3): the tags come through the namer chain over the winning
// document (D1 — the series document for episodes, the item's own for
// films/tv items), InProgress is the positive-progress fact MINUS the
// watched-ledger carve-out (a completed item keeps its progress row, so
// the resume bonus needs hasProgress && !completed), and NewEpisode marks
// an episode with neither a progress nor a watched row discovered in the
// window whose series is started by the batched facts — started means
// progress OR watched (the spec's started-series definition).
//
// startedSeed is the series-scoped startedness the CALLER already derived —
// a ONE-item slice cannot see a series started by a sibling episode, so
// getProgress seeds the fact via seriesStartedFact; listings pass nil (their
// slice is already series-scoped).
//
// The photo carve-out scores ALL ZEROS first (photoModuleID off the namer's
// already-read library row — one comparison, no store read), so no surface
// scoring through this composition carries a photo context bonus; the photo
// GRID's path order is enforced in listItems (the scoredServe skip).
func scoreItems(n naming.Namer, items []store.Item, f recsFacts, startedSeed map[string]bool) []float64 {
	scores := make([]float64, len(items))
	if n.ModuleID == photoModuleID {
		return scores
	}
	started := make(map[string]bool, len(startedSeed))
	for path := range startedSeed {
		started[path] = true
	}
	for _, it := range items {
		if f.hasProgress(it.ID) || f.completed(it.ID) {
			if path := seriesPathOf(it); path != "" {
				started[path] = true
			}
		}
	}
	for i, it := range items {
		path := seriesPathOf(it)
		hasProgress, done := f.hasProgress(it.ID), f.completed(it.ID)
		scores[i] = recs.Score(recs.EntityState{
			InProgress: hasProgress && !done,
			NewEpisode: path != "" && !hasProgress && !done && started[path] && time.Since(it.CreatedAt) <= newEpisodeWindow,
			Tags:       n.ItemTags(it, path),
		}, f.weights)
	}
	return scores
}

// scoreSeries derives one recommendation score per series row, aligned with
// srs, from the series' grouped episodes (D2/D3) — plus the watched law
// (watched-states D1) folded in the SAME walk (the all-episodes fold costs
// nothing; every episode's ledger fact is already read). Started means ANY
// episode carries a progress OR watched row (the spec's definition); the
// InProgress bonus needs a positive progress row that has NOT completed
// (watched-to-the-end does not float); the new-episode bonus needs the
// started series carrying an episode with neither row discovered in the
// window; an unstarted series never carries the bonus (D3). The tags are the
// series document's own genres (D1). Photo libraries have no series rows, so
// no photo case exists here. Both returned slices align with srs.
func scoreSeries(n naming.Namer, srs []store.Series, eps map[string][]store.Item, f recsFacts) ([]float64, []bool) {
	scores := make([]float64, len(srs))
	watched := make([]bool, len(srs))
	for i, sr := range srs {
		started, inProgress, fresh := false, false, false
		allDone := len(eps[sr.RelativePath]) > 0
		for _, ep := range eps[sr.RelativePath] {
			hasProgress, done := f.hasProgress(ep.ID), f.completed(ep.ID)
			if hasProgress || done {
				started = true
			}
			if hasProgress && !done {
				inProgress = true
			}
			if !hasProgress && !done && time.Since(ep.CreatedAt) <= newEpisodeWindow {
				fresh = true
			}
			allDone = allDone && done
		}
		watched[i] = allDone
		scores[i] = recs.Score(recs.EntityState{
			InProgress: inProgress,
			NewEpisode: started && fresh,
			Tags:       n.GenresFor(sr.Document),
		}, f.weights)
	}
	return scores, watched
}

// seriesPathOf reads an item's parsed series anchor
// (parsed.series_relative_path) — the SPA's episode→series join, the same
// one the display composer uses. "" means the item is a film/tv item with no
// series behind it.
func seriesPathOf(it store.Item) string {
	doc := naming.DocMap(it.Document)
	parsed, _ := doc["parsed"].(map[string]any)
	// The composer's strField read, inlined for its one non-naming caller:
	// a non-string (or absent) anchor floors to "" — the film/tv shape.
	path, _ := parsed["series_relative_path"].(string)
	return path
}

// episodesBySeries groups items by their parsed series anchor — the batched
// join behind the series listing's per-series facts (startedness, the fresh
// episode). Items without the anchor land nowhere: films/tv items score as
// their own entities, never into a series.
func episodesBySeries(items []store.Item) map[string][]store.Item {
	out := make(map[string][]store.Item)
	for _, it := range items {
		if path := seriesPathOf(it); path != "" {
			out[path] = append(out[path], it)
		}
	}
	return out
}

// scoredServe reorders rows into the served scored order — recs.Order, the
// ONE comparator (the alphabetical floor, watched-states D4) — and stamps
// each row's rec_score, returning the ordered copy. scores align with the
// input order; watched reads the ledger fact the partition sinks on, fed
// from the SAME batched facts the score composed, never an extra read. IDs
// are unique per surface, so the index map is total.
func scoredServe[T any](rows []T, scores []float64, id func(T) string, name func(T) string, watched func(T) bool, set func(*T, float64)) []T {
	entries := make([]recs.Entry, len(rows))
	pos := make(map[string]int, len(rows))
	for i := range rows {
		entries[i] = recs.Entry{ID: id(rows[i]), DisplayName: name(rows[i]), Score: scores[i], Watched: watched(rows[i])}
		pos[id(rows[i])] = i
	}
	recs.Order(entries)
	out := make([]T, len(rows))
	for i, e := range entries {
		out[i] = rows[pos[e.ID]]
		set(&out[i], e.Score)
	}
	return out
}

// seriesWatched reports the series' watched fact (watched-states): every
// backing episode ledgered — the same all-episodes law the seriesDTO stamp
// derives — so an all-watched series sinks below unwatched ones in the
// grid partition while a partially-watched one stays up (its InProgress
// bonus already floats it). A series with no episode rows is unwatchable,
// so it never counts as watched.
func seriesWatched(eps []store.Item, f recsFacts) bool {
	return allLedgered(eps, f.watched)
}

// allLedgered is the all-episodes law over the ledger membership set: true
// only when eps is non-empty and every episode id sits in the set. The full
// facts read it through seriesWatched; the sort=path opt-out reads it
// directly over its own watchedSet fold (the ledger alone — no score facts).
func allLedgered(eps []store.Item, watched map[string]struct{}) bool {
	if len(eps) == 0 {
		return false
	}
	for _, ep := range eps {
		if _, has := watched[ep.ID]; !has {
			return false
		}
	}
	return true
}

// progressScored is one continue-surface row with its derived score — the
// pair orderByScoreRecency sorts.
type progressScored struct {
	row   store.PlaybackProgress
	score float64
}

// orderByScoreRecency reorders progress rows into the continue surface's
// served order (D7): score descending, then updated_at descending — recency,
// NOT recs.Order's alphabetical floor (this surface's tiebreak is the stamp,
// compared lexically: the exact order the store's own read serves and
// sort=recent restores, over the same formatTime stamps) — item id as the
// deterministic last floor. The comparator is total, so the unstable sort is
// deterministic.
func orderByScoreRecency(entries []progressScored) {
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].score != entries[j].score {
			return entries[i].score > entries[j].score
		}
		if entries[i].row.UpdatedAt != entries[j].row.UpdatedAt {
			return entries[i].row.UpdatedAt > entries[j].row.UpdatedAt
		}
		return entries[i].row.ItemID < entries[j].row.ItemID
	})
}

// scoreProgress derives one recommendation score per progress row, aligned
// with rows (D7), through the SAME scoreItems composition the item listing
// uses: every listed row IS a resume point — the positive-progress fact is
// true by construction, so InProgress (the resume bonus, the point of this
// surface) holds and NewEpisode is impossible (D3's bonus needs an episode
// with NO progress row) — and the tags ride the item's genres via ItemTags.
// The namer is per-library and rows may span libraries, so each row scores
// under its own item's library namer, built once per distinct library. The
// item rows ride per-row point reads: the store has no batched items-by-id
// read, and the one-row-per-item upsert contract bounds the walk.
func (a *app) scoreProgress(ctx context.Context, v access.Viewer, rows []store.PlaybackProgress, f recsFacts) ([]float64, error) {
	items := make([]store.Item, len(rows))
	byLib := make(map[int64][]int, len(rows))
	for i, row := range rows {
		it, err := a.deps.Store.GetItem(ctx, row.ItemID, v)
		if err != nil {
			return nil, err
		}
		items[i] = it
		byLib[it.LibraryID] = append(byLib[it.LibraryID], i)
	}
	namers := make(map[int64]naming.Namer, len(byLib))
	scores := make([]float64, len(rows))
	for libID, idx := range byLib {
		n, ok := namers[libID]
		if !ok {
			var err error
			// 10.4: the scored composition's title walk floors past this
			// viewer's muted sources (v is scoreProgress's caller viewer).
			if n, err = a.namerFor(ctx, libID, v.ChainMutes); err != nil {
				return nil, err
			}
			namers[libID] = n
		}
		lib := make([]store.Item, len(idx))
		for j, i := range idx {
			lib[j] = items[i]
		}
		libScores := scoreItems(n, lib, f, nil)
		for j, i := range idx {
			scores[i] = libScores[j]
		}
	}
	return scores, nil
}

// homeEntity is ONE continue-rail entity at entity grain (home-rail design
// §Interfaces): a touched series — its started-max over ALL touched progress
// rows (ledgered included), its resume-max row (the highest-started
// NON-ledgered one), its max touched-row updated_at, the pre-cut episode
// rows (D7 — read once here, carried so scoring AND the composer never
// re-read), and the two honest floors (Q1's parsed-fact fallback, D2's
// resolution floor) — or a per-item film/tv entity. The carried fields are
// the state the scoreHomeEntities/orderHomeEntities seams and the composer
// consume; change them only together with design §Interfaces.
type homeEntity struct {
	libID int64
	// path is the parsed series anchor; "" marks the Q1 film fallback (the
	// row's document parses no episode facts — the per-item film entity).
	path string
	// film is Q1's parsed-episode-film flag; served is D2's resolution flag
	// (the series row present AND not a tombstone). A fact-carrying entity
	// with served=false is the D2 honest floor: per-item, series fields
	// empty, no next — resolution failure never fabricates a series card.
	film   bool
	served bool
	sr     store.Series
	// id is the ordering law's floor: the ser_ id for a served serial
	// entity, the resume body's itm_ id otherwise.
	id string
	// startS/startE is the started-max over ALL touched rows (ledgered
	// included) — the next pick's anchor. resume/resumeItem is the
	// highest-started NON-ledgered touched row (hasResume false = every
	// touched row ledgered — the anchor-card case); resumeS/resumeE is its
	// parsed pair.
	startS, startE   int64
	hasResume        bool
	resume           store.PlaybackProgress
	resumeItem       store.Item
	resumeS, resumeE int64
	// updated is the entity's max touched-row updated_at (the recency
	// tiebreak), compared lexically — the same RFC3339Nano stamp the
	// store's read serves.
	updated string
	// touched is the entity's touched item rows (the walk's GetItem reads);
	// eps is the series' full episode rows — ONE pre-cut QueryItemsBySeries
	// (D7), read BEFORE the bound cut so the +500 NewEpisode tier that
	// orders the cut is scorable.
	touched []store.Item
	eps     []store.Item
	score   float64
}

// homeEntities derives the rail's entities from the caller's FULL
// positive-progress set (D1 — no input withdrawal): ONE GetItem walk over
// facts.rows, episode-fact grouping by (libraryID, seriesPath), the
// per-series started-max/resume-max folds, ONE pre-cut QueryItemsBySeries
// per served series (D7), and the serve law (D2) — survival iff a resume-max
// exists OR homeNextPick finds a next after the started-max. Rows without
// parseable episode facts stay per-item film entities (Q1); unresolvable or
// tombstoned series floor to the per-item honest entity; ledgered film/tv
// items drop; caught-up-without-next drops. The namers are built ONCE per
// distinct library here and returned shared (D7): scoring and the composer
// consume the same map.
func (a *app) homeEntities(ctx context.Context, v access.Viewer, f recsFacts) ([]homeEntity, map[int64]naming.Namer, error) {
	type entKey struct {
		lib  int64
		path string
	}
	byKey := make(map[entKey]*homeEntity)
	var ents []*homeEntity
	for _, row := range f.rows {
		it, err := a.deps.Store.GetItem(ctx, row.ItemID, v)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				continue // gone between reads — the row serves nothing
			}
			return nil, nil, err
		}
		path, s, e, ok := naming.EpisodeFacts(naming.DocMap(it.Document))
		if !ok {
			// Q1: the per-item film entity — dropped entirely when
			// ledgered (a completed watch has no resume and no next).
			if f.completed(it.ID) {
				continue
			}
			ents = append(ents, &homeEntity{
				libID: it.LibraryID, film: true, id: it.ID,
				hasResume: true, resume: row, resumeItem: it,
				updated: row.UpdatedAt, touched: []store.Item{it},
			})
			continue
		}
		ent := byKey[entKey{it.LibraryID, path}]
		if ent == nil {
			ent = &homeEntity{libID: it.LibraryID, path: path}
			byKey[entKey{it.LibraryID, path}] = ent
			ents = append(ents, ent)
		}
		// Started-max spans ALL touched rows, ledgered included (D3) —
		// the next pick's anchor.
		if s > ent.startS || (s == ent.startS && e > ent.startE) {
			ent.startS, ent.startE = s, e
		}
		// Resume-max is the highest-started NON-ledgered row (D3) — the
		// skip-ahead case keeps it strictly below the started-max.
		if !f.completed(it.ID) {
			if !ent.hasResume || s > ent.resumeS || (s == ent.resumeS && e > ent.resumeE) {
				ent.hasResume = true
				ent.resume, ent.resumeItem = row, it
				ent.resumeS, ent.resumeE = s, e
			}
		}
		if row.UpdatedAt > ent.updated {
			ent.updated = row.UpdatedAt
		}
		ent.touched = append(ent.touched, it)
	}
	// Namers once per distinct library across ALL entities (D7 — films
	// score through them too), then resolution, the pre-cut eps reads, and
	// the serve law.
	namers := make(map[int64]naming.Namer, len(ents))
	for _, ent := range ents {
		if _, has := namers[ent.libID]; has {
			continue
		}
		// 10.4: the scored composition's namer walk floors past this
		// viewer's muted sources (v is homeEntities' caller viewer).
		n, err := a.namerFor(ctx, ent.libID, v.ChainMutes)
		if err != nil {
			return nil, nil, err
		}
		namers[ent.libID] = n
	}
	out := make([]homeEntity, 0, len(ents))
	for _, ent := range ents {
		if ent.film {
			out = append(out, *ent)
			continue
		}
		n := namers[ent.libID]
		cand, resolved := n.SeriesByPath[ent.path]
		if !resolved || cand.Status == "deleted" {
			// D2 floor: the per-item honest entity — series fields empty,
			// no next concept; all-ledgered drops with it.
			if !ent.hasResume {
				continue
			}
			ent.id = ent.resumeItem.ID
			out = append(out, *ent)
			continue
		}
		ent.served, ent.sr, ent.id = true, cand, cand.ID
		eps, err := a.deps.Store.QueryItemsBySeries(ctx, cand, seriesBacking(cand.Document), v)
		if err != nil {
			return nil, nil, err
		}
		ent.eps = eps
		// The serve law (D2) from the SAME pick the composer serves.
		if _, _, next := homeNextPick(eps, ent.startS, ent.startE); ent.hasResume || next {
			out = append(out, *ent)
		}
	}
	return out, namers, nil
}

// scoreHomeEntities scores each entity IN PLACE through the EXISTING scorers
// (D5): a served serial entity through scoreSeries fed an eps map UNIONED
// with the entity's touched items (Q2 — zero extra reads; the resume ≥1000
// tier holds even under document drift); a film or floored entity through
// scoreItems over its resume body item (Q1's fallback never fabricates
// series identity). The namers are homeEntities' map, built once and shared
// downstream (D7).
func scoreHomeEntities(ents []homeEntity, f recsFacts, namers map[int64]naming.Namer) {
	for i := range ents {
		ent := &ents[i]
		n := namers[ent.libID]
		if ent.served {
			eps := map[string][]store.Item{ent.sr.RelativePath: unionTouched(ent.eps, ent.touched)}
			scores, _ := scoreSeries(n, []store.Series{ent.sr}, eps, f)
			ent.score = scores[0]
			continue
		}
		ent.score = scoreItems(n, []store.Item{ent.resumeItem}, f, nil)[0]
	}
}

// unionTouched folds the entity's touched items into its raw eps list
// (D5/Q2): eps first in the store's order, then touched rows the list does
// not already carry (the drift case) — id-deduped, order stable.
func unionTouched(eps, touched []store.Item) []store.Item {
	seen := make(map[string]bool, len(eps)+len(touched))
	out := make([]store.Item, 0, len(eps)+len(touched))
	for _, it := range eps {
		if !seen[it.ID] {
			seen[it.ID] = true
			out = append(out, it)
		}
	}
	for _, it := range touched {
		if !seen[it.ID] {
			seen[it.ID] = true
			out = append(out, it)
		}
	}
	return out
}

// orderHomeEntities reorders the entities into the rail's served order
// (D6): score descending, then the entity's max touched-row updated_at
// descending — recency, compared lexically over the same RFC3339Nano stamps
// the store's own read serves — then the ser_/itm_ id floor. The comparator
// is total, so the unstable sort is deterministic.
func orderHomeEntities(ents []homeEntity) {
	sort.Slice(ents, func(i, j int) bool {
		if ents[i].score != ents[j].score {
			return ents[i].score > ents[j].score
		}
		if ents[i].updated != ents[j].updated {
			return ents[i].updated > ents[j].updated
		}
		return ents[i].id < ents[j].id
	})
}

// seriesStartedFact derives the startedness fact SERIES-scoped: any episode
// of the series with a progress or watched row; one point read, never in a listing loop.
func (a *app) seriesStartedFact(ctx context.Context, v access.Viewer, n naming.Namer, path string, f recsFacts) (bool, error) {
	sr, ok := n.SeriesByPath[path]
	if !ok {
		return false, nil
	}
	eps, err := a.deps.Store.QueryItemsBySeries(ctx, sr, seriesBacking(sr.Document), v)
	if err != nil {
		return false, err
	}
	for _, ep := range eps {
		if f.hasProgress(ep.ID) || f.completed(ep.ID) {
			return true, nil
		}
	}
	return false, nil
}
